function getTerraformTranslation(key, lang) {
    if (terraformTranslations[lang] && terraformTranslations[lang][key]) {
        return terraformTranslations[lang][key];
    }
    if (terraformTranslations.en && terraformTranslations.en[key]) {
        return terraformTranslations.en[key];
    }
    return null;
}

function applyTerraformTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.terraform.')) {
            const translation = getTerraformTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyTerraformTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyTerraformTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyTerraformTranslations(currentLang);
}


